n = 0
for slug, (teams, stuck) in D.items():
    f = f'industries-{slug}.html'; h = open(f).read(); o = h
    a = h.find('Teams we support'); b = h.find('id="common-challenges"') if h.find('id="common-challenges"') > a else h.find('Regulatory Focus')
    # teams block lies between "Who We Help" and the next section
    end = h.find('</section>', a)
    blk = h[a:end]; it = iter(teams)
    blk = re.sub(r'(<p class="info-card__text">)(.*?)(</p>)', lambda m: m.group(1) + html.escape(next(it), quote=False) + m.group(3), blk, flags=re.S)
    h = h[:a] + blk + h[end:]
    c = h.find('id="common-challenges"'); cend = h.find('</section>', c)
    blk = h[c:cend]; it = iter(stuck)
    blk = re.sub(r'(<p class="info-card__text">)(.*?)(</p>)', lambda m: m.group(1) + html.escape(next(it), quote=False) + m.group(3), blk, flags=re.S)
    h = h[:c] + blk + h[cend:]
    if h != o: open(f, 'w').write(h); n += 1
print('industry pages rewritten:', n)
